import type { RefObject } from 'react';
import {
  ASSISTANT_MODES,
    type AssistantMode,
      type Conversation,
        type ModeMetadata,
        } from '../types/assistant';
        import { ChatMessage } from './ChatMessage';

        function getTimeGreeting(name?: string): string {
          const hour = new Date().getHours();
            const base =
                hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';
                  const cleanName = name?.trim();
                    return cleanName ? `${base}, ${cleanName}` : base;
                    }

                    interface ChatCanvasProps {
                      scrollContainerRef: RefObject<HTMLDivElement | null>;
                        onScroll: () => void;
                          activeConversation: Conversation | null;
                            profileName?: string;
                              activeMode: AssistantMode;
                                activeModeMeta: ModeMetadata;
                                  isStreaming: boolean;
                                    streamingConvId: string | null;
                                      lastModelMsgId: string | null;
                                        onModeChange: (mode: AssistantMode) => void;
                                          onSendPrompt: (prompt: string) => void;
                                            onRegenerate: () => void;
                                            }

                                            export function ChatCanvas({
                                              scrollContainerRef,
                                                onScroll,
                                                  activeConversation,
                                                    profileName,
                                                      activeMode,
                                                        activeModeMeta,
                                                          isStreaming,
                                                            streamingConvId,
                                                              lastModelMsgId,
                                                                onModeChange,
                                                                  onSendPrompt,
                                                                    onRegenerate,
                                                                    }: ChatCanvasProps) {
                                                                      return (
                                                                          <main
                                                                                ref={scrollContainerRef}
                                                                                      onScroll={onScroll}
                                                                                            className="flex-1 overflow-y-auto"
                                                                                                >
                                                                                                      {!activeConversation || activeConversation.messages.length === 0 ? (
                                                                                                              <div className="min-h-full flex flex-col justify-center max-w-3xl mx-auto px-4 sm:px-6 py-8 sm:py-12">
                                                                                                                        <div className="space-y-3 mb-8">
                                                                                                                                    <h2 className="font-display text-3xl sm:text-5xl font-extrabold tracking-tight text-black dark:text-white text-balance">
                                                                                                                                                  {getTimeGreeting(profileName)}
                                                                                                                                                              </h2>
                                                                                                                                                                          <p className="text-base sm:text-lg font-semibold text-slate-800 dark:text-slate-400 max-w-xl leading-relaxed">
                                                                                                                                                                                        Ask anything, attach images or documents for analysis, or switch focus mode below to tailor how I assist you.
                                                                                                                                                                                                    </p>
                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                        <div className="mb-6 space-y-2">
                                                                                                                                                                                                                                    <div
                                                                                                                                                                                                                                                  className="inline-flex flex-wrap items-center gap-1 p-1 rounded-xl bg-slate-100 dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800"
                                                                                                                                                                                                                                                                role="tablist"
                                                                                                                                                                                                                                                                              aria-label="Assistant mode"
                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                        {ASSISTANT_MODES.map((m) => (
                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                          key={m.id}
                                                                                                                                                                                                                                                                                                                                                            type="button"
                                                                                                                                                                                                                                                                                                                                                                              role="tab"
                                                                                                                                                                                                                                                                                                                                                                                                aria-selected={activeMode === m.id}
                                                                                                                                                                                                                                                                                                                                                                                                                  onClick={() => onModeChange(m.id)}
                                                                                                                                                                                                                                                                                                                                                                                                                                    className={`min-h-[38px] px-3.5 py-1.5 rounded-lg text-xs sm:text-sm font-medium transition-colors whitespace-nowrap shrink-0 ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                        activeMode === m.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? 'bg-white dark:bg-slate-800 text-slate-900 dark:text-white shadow-xs'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {m.label}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p className="text-xs text-slate-500 dark:text-slate-400">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {activeModeMeta.description}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {activeModeMeta.starters.map((starter) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      key={starter.title}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      type="button"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onClick={() => onSendPrompt(starter.prompt)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="text-left p-4 rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-[#121824] hover:border-blue-500/50 dark:hover:border-blue-400/50 hover:bg-slate-50/70 dark:hover:bg-slate-900/60 transition-colors group"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="font-display text-base font-extrabold text-black dark:text-slate-100 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {starter.title}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="mt-1 text-xs text-slate-500 dark:text-slate-400 line-clamp-2 leading-relaxed">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {starter.prompt}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="max-w-3xl mx-auto px-4 sm:px-6 py-6 space-y-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {activeConversation.messages.map((msg) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <ChatMessage
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      key={msg.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message={msg}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  isStreaming={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  isStreaming &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  streamingConvId === activeConversation.id &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  msg.id === lastModelMsgId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              isLatestModelMessage={msg.id === lastModelMsgId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onRegenerate={onRegenerate}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }